// @ts-strict
// Worker of «Export all my data» and «Import my data» (esporta-dati.js, importa-dati.js): packs files into one stored ZIP (op "zip") or reads one back (op "unzip")
// with the Rust writer/reader of mzlab-wasm, and writes the saved libraries into OPFS (op "opfs"; sync access handles work in every browser, only in a worker).
// Separate from the worker of the engine so it works with or without open files.
// @ts-ignore the engine is generated by wasm-bindgen: it is not in the tree
import init, { zip_len, zip_write, unzip_len, unzip_write } from "./wasm/mzlab_wasm.js";

const ready = init();

/** Writes `files` ({ path, bytes }, paths relative to the OPFS root) one by one; returns the paths that could not be written (a library may be open elsewhere). @param {{ path: string, bytes: Uint8Array }[]} files */
async function writeOpfs(files) {
  const root = await navigator.storage.getDirectory(), failed = /** @type {string[]} */ ([]);
  for (const f of files) {
    try {
      const parts = f.path.split("/"), name = /** @type {string} */ (parts.pop());
      let dir = root; for (const p of parts) dir = await dir.getDirectoryHandle(p, { create: true });
      const h = await /** @type {any} */ (await dir.getFileHandle(name, { create: true })).createSyncAccessHandle();
      try { h.truncate(0); h.write(f.bytes, { at: 0 }); h.flush(); } finally { h.close(); }
    } catch (_) { failed.push(f.path); }
  }
  return failed;
}

onmessage = async ev => {
  const m = ev.data;
  try {
    await ready;
    if (m.op === "unzip") {
      const zip = new Uint8Array(m.zip), out = new Uint8Array(unzip_len(zip));
      unzip_write(zip, out);
      postMessage({ id: m.id, packed: out.buffer }, [out.buffer]);
    } else if (m.op === "opfs") {
      postMessage({ id: m.id, failed: await writeOpfs(m.files) });
    } else {
      const packed = new Uint8Array(m.packed), out = new Uint8Array(zip_len(packed));
      zip_write(packed, out);
      postMessage({ id: m.id, zip: out.buffer }, [out.buffer]);
    }
  } catch (e) {
    postMessage({ id: m.id, error: String(e) });
  }
};
